/**
 * Generates TypeScript files. Print lines of text and identifiers to a
 * {@link File}, and it works out their imports when it renders.
 *
 * ```ts
 * import { file, module } from "@cloudflare/forge/ts";
 *
 * const models = module("pets/models.ts");
 * const f = file("pets/client.ts");
 * f.doc("A client of pets.");
 * f`export interface ${f.ident("Client")} {`;
 * f.indent(() => {
 *   f`get(): Promise<${models.ident("Pet").ty()}>;`;
 * });
 * f`}`;
 * ```
 *
 * renders as:
 *
 * ```ts
 * // Code generated by forge. DO NOT EDIT.
 * /* eslint-disable *\/
 *
 * import type { Pet } from "./models.js";
 *
 * /**
 *  * A client of pets.
 *  *\/
 * export interface Client {
 *   get(): Promise<Pet>;
 * }
 * ```
 *
 * A `File` is a plugin's file as it is: return it from `generate` or
 * `generateGroup`. One with nothing printed renders as nothing, so forge
 * doesn't write it.
 *
 * This is forge's Rust `forge::ts`, and renders the same text, with tagged
 * templates in place of its macros: `` f`…` ``, calling the file, for `p!`, `` frag`…` ``
 * for `frag!`.
 *
 * @module
 */

// This file is the source of plugin/ts.js and plugin/ts.d.ts. It reads
// the forge only through the types of index.ts, so it needs no host, and
// its tests run in Node.

import type { Group, Model, Name } from './index.js';

/** One level of indentation. */
const INDENT = '  ';

/** The number of columns comments and imports are wrapped at. */
const WIDTH = 80;

/**
 * The first lines of every file. They mark it as generated and turn off
 * ESLint.
 */
export const PREAMBLE = '// Code generated by forge. DO NOT EDIT.\n/* eslint-disable */\n\n';

/**
 * Something a line can print. Strings print as they are, and numbers,
 * booleans and bigints as `String` writes them. An {@link Ident} prints
 * under the name the file uses for it, and is imported if it comes from
 * another module. A {@link Model} prints as its identifier,
 * {@link ident.model}. An array prints each of its parts in turn, with
 * nothing between them: use {@link join} for a list with separators.
 *
 * Anything else, such as `undefined` or an object of a plugin's own, is an
 * error, rather than printing as `undefined` or `[object Object]`: use
 * `String(x)` for a value of your own.
 */
export type Part = string | number | boolean | bigint | Ident | Model | readonly Part[];

/** The key that only modules have, which {@link isModule} looks for. */
const MODULE: unique symbol = Symbol('forge.ts.module');

/** The key that only identifiers have, which {@link isIdent} looks for. */
const IDENT: unique symbol = Symbol('forge.ts.ident');

/**
 * A TypeScript module that files can import: a generated file or a
 * package. Make one with {@link module}.
 *
 * A module ending in `.ts` is a generated file, named by its path from the
 * output directory, such as `pets/models.ts`. Other generated files import
 * it by a relative specifier ending in `.js`, such as `./models.js`, which
 * is how TypeScript resolves it. Any other module is a package, such as
 * `zod` or `node:fs`, and files import it by that specifier unchanged.
 */
export interface Module {
  readonly [MODULE]: true;
  /** The path, for a generated file, or the specifier, for a package. */
  readonly path: string;
  /** Whether the module is a generated file. */
  readonly generated: boolean;
  /** Returns the identifier called `name` declared in this module. */
  ident(name: string): Ident;
  /**
   * Returns the module `name` inside the directory `this`:
   * `module("pets").sub("models.ts")` is `pets/models.ts`.
   */
  sub(name: string): Module;
  /** Whether `other` is the same module. */
  equals(other: Module): boolean;
  /** The path. */
  toString(): string;
}

/**
 * A TypeScript identifier: a name and the module that declares it. A file
 * that prints an identifier from another module imports it. Make one with
 * {@link ident}, or a module's `ident`.
 *
 * It is immutable: `ty` and `as` return new identifiers.
 */
export interface Ident {
  readonly [IDENT]: true;
  /** The name, such as `Pet`, or a dotted one such as `Temporal.Instant`. */
  readonly name: string;
  readonly module: Module;
  /**
   * Whether the identifier is only a type. Files import types with
   * `import type`, or with `type` in front of the name when the same
   * declaration also imports values.
   */
  readonly typeOnly: boolean;
  /**
   * The name a file imports the identifier under, as in
   * `import { Name as Alias }`, and uses for it. If the alias is already
   * taken in the file, it still gets `$` appended. A file ignores the alias
   * of its own identifiers, since it doesn't import them.
   */
  readonly alias: string | undefined;
  /** Returns the identifier marked as only a type. */
  ty(): Ident;
  /** Returns the identifier imported under `alias`. */
  as(alias: string): Ident;
  /** The name unchanged, such as `Temporal.Instant`; a file may print an alias instead. */
  toString(): string;
}

/**
 * A TypeScript file: its module and the lines printed to it. Make one with
 * {@link file}.
 *
 * Print a line by calling the file, as in `` f`let pet: ${pet};` ``, and a
 * comment with `doc`. The file renders them only once it knows every
 * import, so it can give conflicting names aliases.
 */
export interface File {
  /**
   * Prints a line: the file's indentation, the template's parts, then a
   * line break.
   *
   * ```ts
   * f`let pet: ${pet};`;
   * ```
   *
   * If the parts print nothing but empty text, the line is blank, with no
   * indentation. Only the start of the line is indented, so the template
   * shouldn't contain line breaks.
   */
  (strings: TemplateStringsArray, ...parts: Part[]): void;
  /**
   * Prints a line of `parts`, in turn, for parts made at run time:
   *
   * ```ts
   * f("let pet: ", pet, ";");
   * f(); // a blank line
   * ```
   */
  (...parts: Part[]): void;
  /** The module of the file. */
  readonly module: Module;
  /** The path of the file, relative to the output directory. */
  readonly path: string;
  /**
   * The rendered file: the preamble, the imports, then the lines printed to
   * the file, or nothing if nothing was printed.
   *
   * The imports list packages first, then generated files, each sorted by
   * specifier, with one declaration per module. A module whose names are
   * all only types is imported with `import type`, and a name used both as
   * a type and as a value is imported as a value. If an imported name
   * clashes with one the file declares or an earlier import, it gets an
   * alias with `$` appended.
   */
  readonly content: string;
  /** Returns an identifier declared in this file. */
  ident(name: string): Ident;
  /**
   * Calls `f` with the file indented one more level, so the lines and
   * comments it prints get two more spaces.
   */
  indent(f: (file: File) => void): void;
  /**
   * Prints `text` as a JSDoc comment at the file's indentation. It trims
   * the text, prints each line after ` * `, and wraps words to fit in 80
   * columns, giving a word longer than a line a line of its own. It escapes
   * `*\/` so the text can't end the comment early, and prints nothing for
   * empty text.
   */
  doc(text: string): void;
  /** Returns the rendered file, as `content` describes it. */
  render(): string;
}

/** What a module's and an identifier's methods share, so each is made once. */
const moduleMethods: ThisType<Module> & Pick<Module, 'ident' | 'sub' | 'equals' | 'toString'> = {
  ident(name) {
    return ident(name, this);
  },
  sub(name) {
    return module(this.path === '' ? name : `${this.path}/${name}`);
  },
  equals(other) {
    return this.path === other.path;
  },
  toString() {
    return this.path;
  },
};

const identMethods: ThisType<Ident> & Pick<Ident, 'ty' | 'as' | 'toString'> = {
  ty() {
    return ident(this.name, this.module, { typeOnly: true, alias: this.alias });
  },
  as(alias) {
    return ident(this.name, this.module, { typeOnly: this.typeOnly, alias });
  },
  toString() {
    return this.name;
  },
};

/** Returns a new module at `path`. */
function makeModule(path: string): Module {
  return Object.freeze(
    Object.assign(Object.create(moduleMethods) as Module, {
      [MODULE]: true as const,
      path,
      generated: path.endsWith('.ts'),
    }),
  );
}

/** Returns the module at `path`: a generated file if it ends in `.ts`, and a package otherwise. */
export const module: {
  (path: string): Module;
  /** The output directory. Its `sub` modules are the top-level files. */
  readonly ROOT: Module;
  /**
   * Returns the directory that holds `group`'s files: the group's path,
   * with each name in camelCase and prefixed with `_` if it starts with a
   * digit. A group `list_all` inside `pet-store` gets `petStore/listAll`.
   * The root group's path is empty, so its directory is `module.ROOT`.
   */
  group(group: Pick<Group, 'path'>): Module;
} = Object.freeze(
  Object.assign((path: string) => makeModule(path), {
    ROOT: makeModule(''),
    group(group: Pick<Group, 'path'>): Module {
      return makeModule(group.path.map((name) => identifier(name.camel())).join('/'));
    },
  }),
);

/** Returns the identifier `name`, declared in `module`. */
export const ident: {
  (name: string, module: Module, options?: { readonly typeOnly?: boolean; readonly alias?: string | undefined }): Ident;
  /**
   * Returns the identifier of `model`: its name in PascalCase, prefixed
   * with `_` if it starts with a digit, declared in the `models.ts` of its
   * group's directory (`module.group`). Call `ty` on it to import it with
   * `import type`.
   *
   * A plugin that names models differently makes its own identifier, and
   * prints that one everywhere it refers to the model.
   */
  model(model: Pick<Model, 'name' | 'group'>): Ident;
} = Object.freeze(
  Object.assign(
    (
      name: string,
      module: Module,
      options: { readonly typeOnly?: boolean; readonly alias?: string | undefined } = {},
    ): Ident => {
      if (!isModule(module)) {
        throw new TypeError(`${JSON.stringify(name)} needs a module, made with module()`);
      }
      return Object.freeze(
        Object.assign(Object.create(identMethods) as Ident, {
          [IDENT]: true as const,
          name,
          module,
          typeOnly: options.typeOnly ?? false,
          alias: options.alias,
        }),
      );
    },
    {
      model(model: Pick<Model, 'name' | 'group'>): Ident {
        return module.group(model.group).sub('models.ts').ident(identifier(model.name.pascal()));
      },
    },
  ),
);

/** Whether `value` is a {@link Module}: one {@link module} made. */
function isModule(value: unknown): value is Module {
  return typeof value === 'object' && value !== null && (value as Partial<Module>)[MODULE] === true;
}

/** Whether `value` is an {@link Ident}: one {@link ident} made. */
function isIdent(value: unknown): value is Ident {
  return typeof value === 'object' && value !== null && (value as Partial<Ident>)[IDENT] === true;
}

/**
 * Returns the parts of a template, in order, to print as part of a line
 * later:
 *
 * ```ts
 * const list = frag`Promise<${pet}[]>`;
 * f`list(): ${list};`;
 * ```
 */
export function frag(strings: TemplateStringsArray, ...parts: Part[]): Part[] {
  return template(strings, parts);
}

/**
 * Returns `parts` with `sep` between each two of them, leaving out the
 * parts that print nothing:
 *
 * ```ts
 * f`const all = [${join(", ", ["a", "", "c"])}];`; // const all = [a, c];
 * ```
 */
export function join(sep: string, parts: Iterable<Part>): Part[] {
  const out: Element[] = [];
  for (const part of parts) {
    const printed = elements(part);
    if (printed.length === 0) {
      continue;
    }
    if (out.length > 0) {
      appendText(out, sep);
    }
    append(out, printed);
  }
  return out;
}

/** What a file keeps: its module, and what has been printed to it. */
interface FileState {
  readonly module: Module;
  /** Text and identifiers, as {@link Element}s. */
  readonly body: Element[];
  /** How many levels to indent the lines printed next. */
  depth: number;
}

/**
 * Returns an empty file at `module`, or at the module with that path.
 *
 * ```ts
 * const f = file("pets/client.ts");
 * f`export interface ${f.ident("Client")} {}`;
 * ```
 */
export function file(at: Module | string): File {
  const state: FileState = {
    module: typeof at === 'string' ? module(at) : isModule(at) ? at : badModule(at),
    body: [],
    depth: 0,
  };
  // A file is a function that prints a line, with the rest of a File as
  // its properties. It is frozen, so none of them can be replaced.
  const print = (...args: Part[]): void => line(state, args);
  const self = print as unknown as File;
  const members: Omit<File, never> = {
    module: state.module,
    get path() {
      return state.module.path;
    },
    get content() {
      return render(state);
    },
    ident: (name) => state.module.ident(name),
    indent: (f) => {
      state.depth++;
      try {
        f(self);
      } finally {
        state.depth--;
      }
    },
    doc: (text) => doc(state, text),
    render: () => render(state),
  };
  Object.defineProperties(print, Object.getOwnPropertyDescriptors(members));
  return Object.freeze(self);
}

function badModule(at: unknown): never {
  throw new TypeError(`a file needs a path or a module made with module(), not ${typeof at}`);
}

/** Prints a line of what a file was called with. */
function line(state: FileState, args: Part[]): void {
  // A tagged template passes its strings as an array with `raw`, which no
  // other array has.
  const [first, ...rest] = args;
  const printed = isTemplate(first) ? template(first, rest) : elements(args);
  if (printed.length > 0) {
    appendText(state.body, INDENT.repeat(state.depth));
    append(state.body, printed);
  }
  appendText(state.body, '\n');
}

/** Prints `text` as a JSDoc comment, as {@link File.doc} describes. */
function doc(state: FileState, text: string): void {
  const body = text.replaceAll('*/', '*\\/').trim();
  if (body === '') {
    return;
  }
  const tab = INDENT.repeat(state.depth);
  const prefix = `${tab} * `;
  appendText(state.body, `${tab}/**\n`);
  for (const line of body.replaceAll('\r\n', '\n').split('\n')) {
    for (const wrapped of wrap(prefix, line)) {
      appendText(state.body, wrapped);
      appendText(state.body, '\n');
    }
  }
  appendText(state.body, `${tab} */\n`);
}

/** Returns the rendered file, as {@link File.content} describes it. */
function render(state: FileState): string {
  if (state.body.length === 0) {
    return '';
  }
  const imports = importsOf(state);
  const aliases = aliasesOf(state, imports);
  let b = PREAMBLE;
  const declarations = declarationsOf(state, imports, aliases);
  if (declarations !== '') {
    b += `${declarations}\n`;
  }
  for (const element of state.body) {
    b += typeof element === 'string' ? element : nameOf(state, element, aliases);
  }
  return `${b.replace(/\n+$/, '')}\n`;
}

/** Whether `id` is declared in the file or in no module, so the file doesn't import it. */
function isLocal(state: FileState, id: Ident): boolean {
  return id.module.equals(state.module) || id.module.path === '';
}

/**
 * Returns the identifiers the file imports, by key, sorted with packages
 * first, then generated files, each by specifier, then by name and alias,
 * and the keys of those used as values.
 */
function importsOf(state: FileState): Imports {
  const values = new Map<string, Import>();
  const types = new Map<string, Import>();
  for (const element of state.body) {
    if (typeof element === 'string' || isLocal(state, element)) {
      continue;
    }
    const imported = importOf(element);
    (element.typeOnly ? types : values).set(imported.key, imported);
  }
  const sorted = [...values.values(), ...[...types.values()].filter((t) => !values.has(t.key))];
  const sortKey = (i: Import) => [rank(i.module), specifier(state, i.module), i.name, i.alias] as const;
  sorted.sort((a, b) => compare(sortKey(a), sortKey(b)));
  return { sorted, values: new Set(values.keys()) };
}

/**
 * Picks the name the file uses for each import: its alias if it has one,
 * otherwise its own name. It appends `$` until the name clashes with
 * neither a name the file declares nor an earlier import, going through the
 * imports in order.
 */
function aliasesOf(state: FileState, imports: Imports): Map<string, string> {
  const taken = new Set<string>();
  for (const element of state.body) {
    if (typeof element !== 'string' && isLocal(state, element)) {
      taken.add(rootName(element.name));
    }
  }
  const aliases = new Map<string, string>();
  for (const i of imports.sorted) {
    let name = i.alias ?? i.name;
    while (taken.has(name)) {
      name += '$';
    }
    taken.add(name);
    aliases.set(i.key, name);
  }
  return aliases;
}

/** Returns the name the file refers to `id` by. */
function nameOf(state: FileState, id: Ident, aliases: Map<string, string>): string {
  if (isLocal(state, id)) {
    return id.name;
  }
  const name = aliases.get(importOf(id).key)!;
  const dot = id.name.indexOf('.');
  return dot === -1 ? name : `${name}${id.name.slice(dot)}`;
}

/** Returns the import declarations of the file. */
function declarationsOf(state: FileState, imports: Imports, aliases: Map<string, string>): string {
  let b = '';
  let previous: Module | undefined;
  for (const group of chunkBy(imports.sorted, (a, b) => a.module.equals(b.module))) {
    const module = group[0]!.module;
    if (previous && rank(previous) !== rank(module)) {
      b += '\n';
    }
    previous = module;
    const allTypes = group.every((i) => !imports.values.has(i.key));
    const names = group.map((i) => {
      let name = i.name;
      const alias = aliases.get(i.key)!;
      if (alias !== name) {
        name = `${name} as ${alias}`;
      }
      if (!allTypes && !imports.values.has(i.key)) {
        name = `type ${name}`;
      }
      return name;
    });
    const head = allTypes ? 'import type ' : 'import ';
    b += importDeclaration(head, names, ` from "${specifier(state, module)}";`);
  }
  return b;
}

/**
 * Returns how the file imports `module`: a package by its specifier, and a
 * generated file by its path relative to the file, ending with `.js`.
 */
function specifier(state: FileState, module: Module): string {
  if (!module.generated) {
    return module.path;
  }
  const slash = state.module.path.lastIndexOf('/');
  const from = slash === -1 ? [] : state.module.path.slice(0, slash).split('/');
  const to = module.path.split('/');
  let shared = 0;
  while (shared < from.length && shared < to.length - 1 && from[shared] === to[shared]) {
    shared++;
  }
  const joined = [...Array<string>(from.length - shared).fill('..'), ...to.slice(shared)].join('/');
  const spec = `${joined.endsWith('.ts') ? joined.slice(0, -3) : joined}.js`;
  return spec.startsWith('../') ? spec : `./${spec}`;
}

/** An identifier a file imports: the root of its name, without whether it is only a type. */
interface Import {
  readonly key: string;
  readonly name: string;
  readonly module: Module;
  readonly alias: string | undefined;
}

/** The identifiers a file imports. */
interface Imports {
  /** Each import once, sorted. */
  readonly sorted: Import[];
  /** The keys of those used as values, and not only as types. */
  readonly values: Set<string>;
}

/** Returns what `id` is imported as. */
function importOf(id: Ident): Import {
  const name = rootName(id.name);
  const key = JSON.stringify([id.module.path, name, id.alias ?? null]);
  return { key, name, module: id.module, alias: id.alias };
}

/** Returns the name a dotted name such as `Temporal.Instant` is imported by. */
function rootName(name: string): string {
  const dot = name.indexOf('.');
  return dot === -1 ? name : name.slice(0, dot);
}

/** Puts packages before generated files. */
function rank(module: Module): number {
  return module.generated ? 1 : 0;
}

/**
 * Compares sort keys element by element, as Rust compares tuples: strings
 * by code unit, and an absent alias before any alias.
 */
function compare(a: readonly unknown[], b: readonly unknown[]): number {
  for (let i = 0; i < a.length; i++) {
    const [x, y] = [a[i], b[i]];
    if (x === y) {
      continue;
    }
    if (x === undefined) {
      return -1;
    }
    if (y === undefined) {
      return 1;
    }
    return (x as string | number) < (y as string | number) ? -1 : 1;
  }
  return 0;
}

/** Splits `items` into runs of neighbours that `same` says go together. */
function chunkBy<T>(items: readonly T[], same: (a: T, b: T) => boolean): T[][] {
  const chunks: T[][] = [];
  for (const item of items) {
    const last = chunks[chunks.length - 1];
    if (last && same(last[last.length - 1]!, item)) {
      last.push(item);
    } else {
      chunks.push([item]);
    }
  }
  return chunks;
}

/**
 * Returns an import declaration: on one line when it fits in 80 columns or
 * has one name, and with a name on each line otherwise.
 */
function importDeclaration(head: string, names: string[], tail: string): string {
  const line = `${head}{ ${names.join(', ')} }${tail}`;
  if (names.length === 1 || line.length <= WIDTH) {
    return `${line}\n`;
  }
  return `${head}{\n${names.map((name) => `${INDENT}${name},\n`).join('')}}${tail}\n`;
}

/**
 * Returns `line` after `prefix`, with words wrapped to fit in 80 columns.
 * Leading spaces, such as a list item's indent, are repeated on each
 * wrapped line.
 */
function wrap(prefix: string, line: string): string[] {
  line = line.replace(/[ \t]+$/, '');
  const lead = /^[ \t]*/.exec(line)![0];
  const words = line.split(/\s+/).filter((word) => word !== '');
  const [first, ...rest] = words;
  if (first === undefined) {
    return [prefix.replace(/ +$/, '')];
  }
  const lines: string[] = [];
  let current = `${prefix}${lead}${first}`;
  let columns = width(current);
  for (const word of rest) {
    const w = width(word);
    if (columns + 1 + w <= WIDTH) {
      current += ` ${word}`;
      columns += 1 + w;
      continue;
    }
    lines.push(current);
    current = `${prefix}${lead}${word}`;
    columns = width(current);
  }
  lines.push(current);
  return lines;
}

/** The number of characters in `s`, counting each code point once, as Rust's `chars` does. */
function width(s: string): number {
  let n = 0;
  for (const _ of s) {
    n++;
  }
  return n;
}

/** Prefixes `s` with `_` if it starts with a digit, so it's a valid identifier. */
function identifier(s: string): string {
  return /^[0-9]/.test(s) ? `_${s}` : s;
}

/**
 * What parts print as: text, or an identifier the file resolves when it
 * renders. Adjacent text is always joined into one element, and empty text
 * never kept, so nothing printed is no elements.
 */
type Element = string | Ident;

/** Returns a template's strings and parts, interleaved, as elements. */
function template(strings: TemplateStringsArray, parts: Part[]): Element[] {
  const out: Element[] = [];
  strings.forEach((s, i) => {
    appendText(out, s);
    if (i < parts.length) {
      append(out, parts[i]);
    }
  });
  return out;
}

/** Whether `part` is the strings of a tagged template, rather than a part. */
function isTemplate(part: Part | undefined): part is TemplateStringsArray {
  return Array.isArray(part) && Object.prototype.hasOwnProperty.call(part, 'raw');
}

/** Returns what `part` prints as. */
function elements(part: Part): Element[] {
  const out: Element[] = [];
  append(out, part);
  return out;
}

/** Appends text to `out`. */
function appendText(out: Element[], s: string): void {
  if (s === '') {
    return;
  }
  const last = out.length - 1;
  if (typeof out[last] === 'string') {
    out[last] += s;
  } else {
    out.push(s);
  }
}

/** Appends what `part` prints as to `out`, or throws if it is not a {@link Part}. */
function append(out: Element[], part: Part | undefined): void {
  switch (typeof part) {
    case 'string':
      appendText(out, part);
      return;
    case 'number':
    case 'boolean':
    case 'bigint':
      appendText(out, String(part));
      return;
    case 'object':
      if (Array.isArray(part)) {
        for (const p of part as readonly Part[]) {
          append(out, p);
        }
        return;
      }
      if (isIdent(part)) {
        out.push(part);
        return;
      }
      if (part !== null && isModel(part)) {
        out.push(ident.model(part));
        return;
      }
      break;
  }
  throw new TypeError(`cannot print ${part === null ? 'null' : typeof part}`);
}

/** Whether `part` is a {@link Model}, which has no `print` of its own. */
function isModel(part: object): part is Model {
  const model = part as Partial<Model>;
  return (
    typeof model.schemaName === 'string' && typeof (model.name as Partial<Name> | undefined)?.pascal === 'function'
  );
}
